  function cleanPark(val) {
    if (val == null || String(val).trim() === "") return "";
    const key = String(val).toLowerCase().replace(/[^a-z]/g, "");
    return parkMap[key] || "REVIEW";
  }

  function normName(val) {
    return String(val || "").trim().toLowerCase().replace(/\./g, "").replace(/\s+/g, " ");
  }

