    Logger.log("DRY RUN | Raw: " + totalRaw + " | Consolidated: " + consolidated +
      " | KEPT: " + counts.KEPT + " | MERGED: " + counts.MERGED +
      " | REVIEW: " + counts.REVIEW);
    outData.slice(0, 25).forEach(row => Logger.log(row.join(" | ")));
    if (outData.length > 25) Logger.log("... (" + (outData.length - 25) + " more)");
  } else {
    // -- Consolidated-preview sheet --
    let prev = ss.getSheetByName("Consolidated-preview");
    if (prev) ss.deleteSheet(prev);
    prev = ss.insertSheet("Consolidated-preview");
    prev.appendRow(outHeaders);
    if (outData.length) {
      prev.getRange(2, 1, outData.length, outHeaders.length).setValues(outData);
    }
    prev.getRange(2, 1, Math.max(outData.length, 1), 1)
        .setNumberFormat("yyyy-mm-dd hh:mm");
    prev.getRange(2, 5, Math.max(outData.length, 1), 1)
        .setNumberFormat("@");
    prev.getRange(2, outHeaders.length, Math.max(outData.length, 1), 1)
        .setWrapStrategy(SpreadsheetApp.WrapStrategy.WRAP);
    outHeaders.forEach((_, i) => prev.autoResizeColumn(i + 1));

    // -- Consolidation-Summary sheet --
    let sumSheet = ss.getSheetByName("Consolidation-Summary");
    if (sumSheet) ss.deleteSheet(sumSheet);
    sumSheet = ss.insertSheet("Consolidation-Summary");
    sumSheet.getRange(1, 1, 6, 2).setValues([
      ["Metric",            "Count"],
      ["Total raw rows",    totalRaw],
      ["Consolidated rows", consolidated],
      ["KEPT",              counts.KEPT],
      ["MERGED",            counts.MERGED],
      ["REVIEW",            counts.REVIEW]
    ]);
    sumSheet.getRange(1, 1, 1, 2).setFontWeight("bold");
    sumSheet.autoResizeColumn(1);
    sumSheet.autoResizeColumn(2);

    Logger.log("Done | Raw: " + totalRaw + " → Consolidated: " + consolidated +
      " (KEPT: " + counts.KEPT + ", MERGED: " + counts.MERGED +
      ", REVIEW: " + counts.REVIEW + ")");
  }
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("🧹 Cleaning")
    .addItem("Run consolidation", "cleanAndConsolidate")
    .addToUi();
}
```

## Changes from v4

| Change | Detail |
|---|---|
| **No more `alert()` calls** | Both dry-run and live paths now only use `Logger.log()`. No pop-ups. |
| **Consolidation-Summary sheet** | Created (or replaced) alongside the preview. Five rows: total raw, consolidated, KEPT, MERGED, REVIEW. Header row bolded, columns auto-sized. |
| **Log message** | Single summary line logged either way so you can confirm counts in **View → Logs** without interruption. |

Everything else — `DRY_RUN=false`, `KEEP_FIRST=true`, phone formatting, tiebreaker, merge logic — is unchanged.
